import java.util.*;

public class Main {
    static long cheapest(long[] price, long[][] qty, long[] offerPrice, long[] needs, Map<String, Long> memo) {
        String key = Arrays.toString(needs);
        Long found = memo.get(key);
        if (found != null) return found;
        long best = 0;
        for (int i = 0; i < needs.length; i++) best += price[i] * needs[i];
        for (int o = 0; o < qty.length; o++) {
            boolean fits = true;
            for (int i = 0; i < needs.length; i++) {
                if (qty[o][i] > needs[i]) fits = false;
            }
            if (!fits) continue;
            long[] rest = needs.clone();
            for (int i = 0; i < needs.length; i++) rest[i] -= qty[o][i];
            best = Math.min(best, offerPrice[o] + cheapest(price, qty, offerPrice, rest, memo));
        }
        memo.put(key, best);
        return best;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] price = new long[(int) n];
        for (int i = 0; i < price.length; i++) price[i] = sc.nextLong();
        long s = sc.nextLong();
        long[][] qty = new long[(int) s][(int) n];
        for (int i = 0; i < qty.length; i++) {
            for (int j = 0; j < qty[i].length; j++) {
                qty[i][j] = sc.nextLong();
            }
        }
        long[] offerPrice = new long[(int) s];
        for (int i = 0; i < offerPrice.length; i++) offerPrice[i] = sc.nextLong();
        long[] needs = new long[(int) n];
        for (int i = 0; i < needs.length; i++) needs[i] = sc.nextLong();

        System.out.println(cheapest(price, qty, offerPrice, needs, new HashMap<>()));
    }
}
